import {water02Data as data} from './water02-data.js?v=20261028-water02';
import {developmentPaths} from './development-data.js?v=20261026-development01';
import {UK_PATH} from './uk-outline.js?v=20261023-geography01';
import {water01Evidence} from './model-water01.js?v=20261028-water01';
export {water02Data} from './water02-data.js?v=20261028-water02';
export const water02Views={
 'dev-water2-use-differences':[['irrigation','Climate and irrigation'],['cooling','Industry and reuse'],['services','Household services'],['countries','Compare real shares']],
 'dev-water2-uk-supply':[['map','Rain and demand'],['seasons','Seasonal mismatch'],['leaks','Leaking supply mains'],['sewers','Combined sewer pressure']],
 'dev-water2-developing-supply':[['rain','Limited inputs'],['pollution','Downstream quality'],['delivery','Safe service chain'],['evidence','Read rural evidence']],
 'dev-water2-stakeholders':[['roles','Interests and constraints'],['map','Read the stress map'],['allocation','Upstream and downstream'],['decision','Test the proposal']],
 'dev-water2-desalination':[['ro','Reverse osmosis'],['thermal','Evaporate and condense'],['balance','Follow both outputs'],['tradeoffs','Judge feasibility']]
};
export const water02Requirements=Object.fromEntries(Object.entries(water02Views).map(([k,v])=>[k,v.map(x=>x[0])]));
export const water02Animated=(k,v)=>({'dev-water2-use-differences':['irrigation','cooling'],'dev-water2-uk-supply':['seasons','leaks','sewers'],'dev-water2-developing-supply':['rain','pollution','delivery'],'dev-water2-stakeholders':['allocation'],'dev-water2-desalination':['ro','thermal']}[k]||[]).includes(v);
export const stressClass=v=>v<25?0:v<50?1:v<75?2:v<=100?3:4;
export const desalBalance=(feed,product,salt)=>({brine:feed-product,salt,feedConcentration:salt/feed,brineConcentration:salt/(feed-product)});
export const deliveredWater=(input,leak)=>input-leak;
const T=(x,y,s,z=12)=>`<text x="${x}" y="${y}" font-size="${z}">${s}</text>`;
const L=(d,c='#b9cdd0',w=2)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;
const D=(x,y,c='#b3d3db',r=5)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}" stroke="#f1e4ce"/>`;
const X=(x,y)=>`<path d="M${x-4} ${y-4}l8 8m-8 0l8-8" stroke="#edb396" stroke-width="2.5"/>`;
const B=(x,y,w,a,b)=>`<rect x="${x}" y="${y}" width="${w}" height="${b?64:40}" rx="10" fill="#35566b" stroke="#a6c1c8"/>`+T(x+12,y+24,a)+(b?T(x+12,y+47,b,11):'');
const flow=(x,y,a,b,t,c='#b3d3db')=>L(`M${x} ${y}L${a} ${b}`)+D(x+(a-x)*t,y+(b-y)*t,c);
const F=(b,c)=>`<svg viewBox="0 0 440 350" style="background:#203e53;border-radius:12px" role="img" aria-label="${c.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><g fill="#f0f1e9" font-family="sans-serif">${b}</g></svg><p class="geo-caption">${c}</p>`;
const A=(u,t)=>`<a href="${u}" target="_blank" rel="noopener">${t}</a>`;
const sources={use:A('https://data.worldbank.org/indicator/ER.H2O.FWAG.ZS','FAO/WDI sector evidence')+' · '+A('https://unstats.un.org/sdgs/report/2025/Goal-06/','UN2025 water-use context')+'. Mechanisms are conceptual; matching2022 country shares are examples, not causal proof that income determines use. Reuse can reduce withdrawals without eliminating consumption or impacts.',uk:A('https://weather.metoffice.gov.uk/learn-about/weather/types-of-weather/rain/how-much-does-it-rain-in-the-uk','Met Office1991–2020 rainfall pattern')+' · '+A(data.england.source,'EA2025 framework, updated 27 August 2026')+' · '+A('https://www.gov.uk/government/publications/storm-overflows-policy-and-guidance/storm-overflows-policy-and-guidance','Defra combined-sewer guidance')+'. Qualitative pattern and illustrative processes, not measured regional rainfall polygons or a current local warning. NaturalEarth public-domain generalised UK outline. Supply mains and sewers are separate systems.',rural:A(data.rural.source,'WHO/UNICEF release,26August2025')+'. Global rural people, not a developing-country-only sample. Safely managed means on premises, available when needed and free from contamination. Lack of this standard does not imply all use surface water. Direct source download403; primary webpage verified.',stress:A(data.stress.source,'FAO AQUASTAT via WDI,2022')+' · '+A('https://databank.worldbank.org/metadataglossary/world-development-indicators/series/ER.H2O.FWST.ZS','Indicator metadata')+' · '+A('https://www.naturalearthdata.com/about/terms-of-use/','Natural Earth public-domain geometry')+'. Withdrawals / total renewable resources after environmental needs. Annual national estimates; not household access or local seasonal pressure. Six-country extract, not full-world/UK-zone coverage. WDI CC BY4.0; raw JSON retained.',desal:A('https://www.energy.gov/cmei/femp/best-management-practice-14-alternative-water-sources','DOE FEMP desalination')+' · '+A('https://www.usgs.gov/water-science-school/science/desalination','USGS thermal separation')+'. Diagrams simplify pretreatment, membranes, energy recovery and post-treatment. Particle shapes are symbols, not molecular sizes or literal pores. No universal plant efficiency, purity, cost or environmental outcome is implied.',process:A('https://www.unesco.org/reports/wwdr/en/2024/s','UNESCO water availability')+' · '+A(data.rural.source,'WHO/UNICEF service standard')+'. Invented quantities, positions and timings. Tokens show direction/sequence, not measured rates, contaminant concentration or treatment instructions. Replay restarts the teaching example.'};
const S=k=>`<details class="geo-chart-values"><summary>Sources &amp; model limits</summary><p class="geo-caption">${sources[k]}</p></details>`;
const table=(cap,heads,rows)=>`<details class="geo-chart-values"><summary>Read the source values</summary><table class="geo-data geo-water-data"><caption>${cap}</caption><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${r[0]}</th>${r.slice(1).map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></details>`;
export function water02Evidence(k='stress'){
 let b='',c='';
 if(k==='countries')return water01Evidence('countries');
 if(k==='england'){b=T(20,30,'ENGLAND · PUBLIC SUPPLY ·2055',14)+T(20,54,'Conditional deficit scenarios · Ml/day · zero baseline',11);for(const[i,[n,v]]of data.england.scenarioRows.entries()){const y=110+i*100;b+=T(20,y-20,n,13)+`<rect x="20" y="${y}" width="${v/5000*345}" height="33" fill="${i?'#abc7b2':'#edb396'}"/>`+T(27+v/5000*345,y+23,String(v),12);}b+=L('M20 292H365')+T(20,314,'0',10)+T(166,314,'2,500',10)+T(335,314,'5,000',10);c='EA framework 2025, updated 27 August 2026. Two England planning scenarios, not observed current UK shortages or two amounts to add. The second assumes 2025–30 actions are delivered.';return F(b,c)+S('uk')+table('Conditional England public-supply deficits in 2055',['Scenario','Ml/day'],data.england.scenarioRows);}
 if(k==='rural'){b=T(20,30,'SAFELY MANAGED DRINKING WATER',13)+T(20,54,'% of GLOBAL RURAL people · JMP 2025 release',11);for(const[i,[year,v]]of data.rural.rows.entries()){const y=118+i*105;b+=T(20,y-20,year,16)+`<rect x="20" y="${y}" width="${v*4}" height="35" fill="${i?'#abc7b2':'#a9c3cc'}"/>`+T(30+v*4,y+25,v+'%',15);}b+=L('M20 293H420')+T(20,315,'0%',10)+T(205,315,'50%',10)+T(390,315,'100%',10);c='WHO/UNICEF 2025 release, estimates for 2015 and 2024. Rural global coverage of a defined service standard, not water volume, a country ranking or the share drinking surface water.';return F(b,c)+S('rural')+table('Global rural safely managed drinking-water coverage',['Year','Coverage %'],data.rural.rows);}
 const colors=['#c8d7cd','#a3beb0','#d8c9a4','#edb396','#d2867b'];b=T(20,27,'WATER STRESS · SIX COUNTRIES ·2022',13)+T(20,47,'Withdrawal / defined renewable availability · North ↑',10)+`<rect x="20" y="55" width="400" height="200" fill="#294f65"/>`+developmentPaths.map(p=>{const row=data.stress.rows.find(r=>r.code===p.code);return `<path d="${p.d}" fill="${row?colors[stressClass(row.value)]:'#647a82'}" stroke="#203e53" stroke-width="0.5"/>`;}).join('');for(const[i,n]of ['<25','25–<50','50–<75','75–100','>100'].entries()){const x=20+i*81;b+=`<rect x="${x}" y="269" width="14" height="13" fill="${colors[i]}"/>`+T(x,300,n+'%',10);}b+=T(20,327,'Grey = not selected · national average ≠ local access',11);c='2022 national water-stress estimates after environmental needs. Values can exceed100% of the defined renewable availability. The UK national average does not describe each catchment or season; grey is not selected, not zero.';return F(b,c)+S('stress')+table('FAO/WDI 2022 water stress, displayed 1 decimal',['Country','% defined availability'],data.stress.rows.map(r=>[r.name,r.value.toFixed(1)]));
}
const river=t=>`<path d="M20 193Q120 150 220 193T420 193" fill="none" stroke="#82a9ba" stroke-width="32"/>`+D(30+380*t,193+15*Math.sin(t*Math.PI*2));
export function water02Scene(k,v,t=0){if(!water02Views[k])return '';if(!water02Requirements[k].includes(v))v=water02Requirements[k][0];t=water02Animated(k,v)?Math.max(0,Math.min(1,Number(t)||0)):0;let b='',c='',s='process';
 if(k==='dev-water2-use-differences'){
 s='use';if(v==='countries')return water02Evidence('countries');
 if(v==='irrigation'){b=T(20,30,'LESS EFFECTIVE RAIN → MORE IRRIGATION',13)+`<path d="M20 266H420V310H20Z" fill="#80937f"/>`+Array.from({length:5},(_,i)=>L(`M${160+i*48} 266V220m0 20l-12-13m12 3l12-13`,'#b2c5a6',3)).join('')+B(20,78,150,'River / aquifer','Finite source')+flow(100,150,100,210,t)+L('M100 210H400')+D(100+300*t,210)+T(180,103,'Crop choice / season',13)+T(180,130,'Irrigation method',13)+T(20,335,'Invented layout; rainfall itself is not a withdrawal',10);c='Conceptual irrigation transfer. Climate and crop needs affect demand; this animation does not measure a farm’s withdrawals or guarantee water savings from one technology.';}
 else if(v==='cooling'){b=T(20,30,'COOLING: REUSE CAN REDUCE WITHDRAWALS',12)+B(20,80,150,'Fresh input','New withdrawal')+B(240,80,180,'Cooling process','Some heat removed')+B(240,245,180,'Recirculating loop','Needs energy / upkeep')+flow(170,115,232,115,t)+flow(330,150,330,237,t)+L('M240 278H200V115H232')+D(200,278-163*t)+T(20,235,'Some loss / discharge',11)+T(20,260,'can remain.',11);c='Conceptual recirculating cooling. Reuse can reduce fresh withdrawals for a service; it does not eliminate evaporation, energy use, discharge or maintenance.';}
 else{b=T(20,30,'ADEQUATE SERVICE ≠ UNLIMITED USE',13)+B(20,70,400,'Can people access reliable water?','Pipes / affordability / quality / maintenance')+B(20,165,400,'How much does the service require?','Appliances / lifestyles / efficient equipment')+B(20,260,400,'What is the percentage denominator?','Sector volume relative to all withdrawals');c='A household-service framework. Low recorded use may indicate unmet needs; a falling share can coexist with a rising domestic volume.';}
 }
 if(k==='dev-water2-uk-supply'){
 s='uk';if(v==='map'){b=T(20,28,'UK · BROAD RAINFALL / DEMAND MISMATCH',12)+`<g transform="translate(12 48) scale(.9)"><path d="${UK_PATH}" fill="#86a69e" stroke="#d0dbd0" stroke-width="1.5"/></g>`+L('M110 145H270')+T(277,142,'North / west',13)+T(277,164,'Generally wetter',11)+L('M205 257H270')+T(277,250,'South / east',13)+T(277,272,'Generally drier',11)+T(277,299,'Many major users',11)+T(20,333,'Qualitative annotations · not rainfall or demand polygons',10);c='Generalised UK outline with broad climate/demand annotations. Places vary within these areas; no measured rainfall surface, population-density raster or UK stress-zone map is implied.';}
 else if(v==='seasons'){const stock=90-35*t;b=T(20,30,'WINTER INPUTS ≠ GUARANTEED SUMMER SUPPLY',12)+B(20,68,190,'Wet-season recharge','Storage is finite')+B(230,68,190,'Summer pressure','Evaporation / extra use')+`<rect x="85" y="170" width="270" height="120" fill="#294f65" stroke="#bdcfc7"/><rect x="85" y="${290-stock}" width="270" height="${stock}" fill="#9abdc6"/>`+flow(365,220,420,220,t,'#edb396')+flow(220,162,220,138,t,'#d8c9a4')+T(100,267,'Illustrative store: '+stock.toFixed(0),15)+T(20,329,'Timing and amount depend on the catchment.',11);c='An invented seasonal drawdown, not a measured UK hydrograph. Limited recharge/storage, evaporation and extra demand can combine to create a summer gap.';}
 else if(v==='leaks'){b=T(20,30,'DRINKING-WATER MAIN · LOSS BEFORE USE',12)+B(20,75,400,'Teaching input 100 units','20 leak; 80 reach users; no other losses assumed')+L('M35 210H405','#a4c5cd',16)+D(35+370*t,210)+L('M220 215V290','#edb396',7)+D(220,215+75*t,'#edb396')+T(25,180,'Input',12)+T(325,180,'Users',12)+T(240,287,'Leak',12)+T(20,329,'This main is distinct from a sewer.',11);c='An invented supply-main balance. Repair can reduce a delivery loss; this does not simulate contamination of a main or automatically increase sewer capacity.';}
 else{b=T(20,30,'COMBINED SEWER · TWO INPUTS',13)+B(20,65,180,'Rain runoff','Variable storm input')+B(240,65,180,'Foul wastewater','Homes / businesses')+flow(110,138,180,200,t)+flow(330,138,250,200,t)+L('M35 218H405','#809eaa',15)+D(40+365*t,218)+L('M220 225V290H405','#edb396',6)+D(220+185*t,290,'#edb396')+T(25,250,'Capacity exceeded → possible overflow',11)+T(235,318,'Receiving watercourse',11);c='Conceptual combined-sewer overflow when inflow exceeds system capacity. Ageing assets and growing runoff/demand can add pressure. Drinking mains are not connected in this diagram; it is not a current spill or compliance assessment.';}
 }
 if(k==='dev-water2-developing-supply'){
 if(v==='evidence')return water02Evidence('rural');
 if(v==='rain'){b=T(20,30,'LOW INPUTS CAN LIMIT RENEWABLE SUPPLY',12)+B(20,65,400,'One possible dry-region constraint','Low annual rain / high evaporation / drought')+`<path d="M20 250Q120 220 220 250T420 250V305H20Z" fill="#8d967f"/>`+flow(120,140,120,240,t)+flow(300,240,300,140,t,'#edb396')+T(20,331,'Not a description of every developing region.',11);c='Illustrative dry-region inputs/losses. Emerging and developing countries include varied climates; income does not determine rainfall.';}
 else if(v==='pollution'){b=T(20,30,'POLLUTION CAN MOVE DOWNSTREAM',13)+river(t)+B(20,65,185,'Untreated waste','Sewage / runoff / industry')+flow(110,138,150,180,t,'#edb396')+X(150+220*t,190)+B(230,255,190,'Downstream source','Quality must be assessed');c='Symbolic downstream contaminant transport, not measured pollutant concentration or natural purification. A clear-looking source can still be unsafe.';}
 else{b=T(20,30,'SAFE SERVICE NEEDS ALL THREE DIMENSIONS',12)+B(20,65,400,'Water free from contamination','Appropriate source protection / treatment')+B(20,160,400,'Available when needed','Reliable operation / storage / maintenance')+B(20,255,400,'Located on premises','Distribution and equitable access')+flow(407,133,407,152,t)+flow(407,228,407,247,t);c='A conceptual safe-service chain. Treatment alone is not proof of reliable on-premises access; this is not a household purification procedure.';}
 }
 if(k==='dev-water2-stakeholders'){
 if(v==='map')return water02Evidence('stress');s='stress';
 if(v==='roles'){b=T(20,30,'ONE RESOURCE · DIFFERENT CONCERNS',13)+B(20,65,190,'Individuals','Needs / bills / livelihoods')+B(230,65,190,'Organisations','Production / river protection')+B(20,190,190,'Governments','Services / growth / nature')+B(230,190,190,'Within-group differences','Constraints / values / location')+T(20,329,'Possible concerns, not a survey of fixed opinions.',10);c='A stakeholder framework: organisations include different kinds of bodies and individuals weigh several concerns. Roles do not establish a unanimous opinion.';}
 else if(v==='allocation'){b=T(20,30,'UPSTREAM CHOICES AFFECT DOWNSTREAM',12)+river(t)+B(20,65,190,'Upstream abstraction','Farm / town / industry')+flow(150,180,150,140,t,'#edb396')+B(230,255,190,'Downstream needs','Users and ecosystems')+T(20,325,'Fixed-flow illustration; real inflows/returns vary.',11);c='A hypothetical allocation mechanism: taking more from a fixed flow can reduce immediate downstream flow. Not a measured catchment, legal entitlement or fixed stakeholder preference.';}
 else{b=T(20,30,'TEST AN ALLOCATION PROPOSAL',13)+B(20,65,400,'Compare like-for-like evidence','Seasonal balances / quality / uncertainty')+B(20,160,400,'Include affected groups','Donor and recipient users / livelihoods / ecosystems')+B(20,255,400,'Explain tradeoffs and alternatives','Costs / benefits / basic needs / review');c='A decision framework without a universal winning policy. Consultation tests evidence and interests; it does not guarantee consensus or demonstrate a student’s extended written argument.';}
 }
 if(k==='dev-water2-desalination'){
 s='desal';if(v==='ro'){const move=Math.max(0,(t-.25)/.75);b=T(20,30,'REVERSE OSMOSIS · PRESSURE THEN TRANSFER',12)+T(20,57,t<.25?'1 · Pump builds pressure':'2 · Water crosses; salts concentrate',12)+`<rect x="30" y="100" width="380" height="150" rx="10" fill="#2d5065" stroke="#a5c4cc"/><path d="M220 100V250" stroke="#c5d4bc" stroke-width="10"/>`+T(45,91,'Saline feed',12)+T(262,91,'Product water',12)+D(60+280*move,155)+D(85+270*move,205)+X(115,165)+X(165,215)+X(100,225)+flow(80,260,80,310,move,'#edb396')+T(100,306,'Concentrated brine',12)+T(250,280,'Selective membrane',11)+T(20,334,'Circles = water · crosses = salts · symbolic sizes',10);c='Pressure-driven selective transport; no boiling. Most salts remain in the concentrate; real product is not perfectly salt-free and needs appropriate further treatment. Pretreatment and energy recovery are simplified.';}
 else if(v==='thermal'){const step=t<.5?t*2:(t-.5)*2;const x=t<.5?100+120*step:220+140*step,y=t<.5?230-130*step:100+130*step;b=T(20,30,'THERMAL: EVAPORATE → CONDENSE',13)+`<path d="M40 150V275H180V150" fill="#82aab8" stroke="#c8d8d2" stroke-width="2"/>`+L('M110 150V100H350V240','#d4d8ca',5)+D(x,y)+X(80,230)+X(125,250)+T(35,310,'Heat input',12)+L('M60 300V283M90 300V283M120 300V283','#edb396',3)+T(235,80,'Cooling removes heat',12)+B(260,245,160,'Liquid product','Further treatment')+T(20,333,'Dissolved salts remain in concentrate; not all contaminants.',10);c='Water evaporates then condenses into liquid product. Heating alone does not collect freshwater. Salt symbols remain; timing, shape, phase boundary and energy inputs are schematic.';}
 else if(v==='balance'){b=T(20,30,'IDEALISED SEPARATION · TWO OUTPUTS',13)+B(20,65,400,'Feed 100 units with 3 salt units','Hypothetical volumes; no other losses')+L('M220 138V170M220 170H115V210M220 170H325V210')+B(20,220,190,'Product 40 units','Salt-free idealisation')+B(230,220,190,'Brine 60 units','Retains 3 salt units')+T(20,329,'Not a real recovery rate or perfect membrane claim.',10);c='Invented mass-balance example: feed volume equals product plus brine; retained salt is in less liquid. Real plants have residual salt, other flows and different recovery conditions.';}
 else{b=T(20,30,'DESALINATION: FEASIBILITY, NOT A GUARANTEE',12)+B(20,65,400,'Production and reliable access','Saline feed / energy / treatment / pipes / upkeep')+B(20,160,400,'Costs and environmental management','Finance / intake / brine / energy source')+B(20,255,400,'Compare alternative ways to close the gap','Leak repair / reuse / efficiency / adequate services');c='A conditional evaluation framework. Desalination can diversify supply, but a plant does not automatically deliver affordable, safe water or eliminate ecological effects.';}
 }
 return F(b,c)+S(s);
}
